// Handle empty or invalid input
if (!items || !Array.isArray(items) || items.length === 0) {
  return [{ json: { conversation_so_far: "" } }];
}

// Extract rows (supporting both raw and .json-wrapped items)
const rows = items.map(i => i.json ?? i).filter(r => r && r.role && r.content);

// Sort by created_at if available
rows.sort((a, b) => new Date(a.created_at || 0) - new Date(b.created_at || 0));

// Build readable convo string (keep content raw)
const conversation = rows
  .map(r => `${r.role.toUpperCase()}: ${r.content}`)
  .join("\n\n");

// Return formatted result
return [{ json: { conversation_so_far: conversation } }];

// n8n Function Node

// Get input data
const items = $input.all();

// Transform each item
return items.map(item => {
  const data = item.json;

  // Build the text
  const combined = `User input: "${data.prompt}". Query generated to answer user: "${data.query}". Data returned from executing the query: [ ${data.tableText} ], if its empty mention no data was found and do not try to generate data`;

  return {
    json: {
      input: combined,
      sessionId: data.sessionId || "unknown-session"
    }
  };
});

// n8n Function node
const item = $input.first().json;

// Gemini expects "contents" not "messages"
const body = {
  contents: [
    {
      role: "user",
      parts: [
        {
          text: `${item.prompt}\n\n${item.input}`
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0,
    topK: 40,
    topP: 0.95,
    maxOutputTokens: 1024
  }
};

return [{ json: body }];
return [
  {
    out: body
  }
];

const sessionId = $input.first().json.sessionId;
const aiMsg = $input.first().json.output; // fixed variable name

return [
  {
    json: {
      role: "Analysis_Agent",
      content: aiMsg,
      session_id: sessionId,
    }
  }
];
